package api

import (
	"context"
	"encoding/base64"
	"time"

	"go.uber.org/zap"

	"taskai/ent"
	"taskai/ent/pageversion"
	"taskai/ent/wikiblock"
	"taskai/ent/wikipage"
)

// StartIndexingWorker starts a background worker that periodically indexes wiki content
func (s *Server) StartIndexingWorker(ctx context.Context) {
	ticker := time.NewTicker(2 * time.Minute)
	defer ticker.Stop()

	s.logger.Info("Starting wiki indexing worker",
		zap.Duration("interval", 2*time.Minute),
	)

	// Run immediately on startup
	s.indexPages(ctx)

	for {
		select {
		case <-ctx.Done():
			s.logger.Info("Indexing worker shutting down")
			return
		case <-ticker.C:
			s.indexPages(ctx)
		}
	}
}

// indexPages finds pages that need indexing and indexes them
func (s *Server) indexPages(parentCtx context.Context) {
	ctx, cancel := context.WithTimeout(parentCtx, 2*time.Minute)
	defer cancel()

	// Find pages that have been updated recently (within last 3 minutes)
	pages, err := s.db.Client.WikiPage.Query().
		Where(wikipage.UpdatedAtGTE(time.Now().Add(-3 * time.Minute))).
		All(ctx)
	if err != nil {
		s.logger.Error("Failed to fetch pages for indexing",
			zap.Error(err),
		)
		return
	}

	if len(pages) == 0 {
		s.logger.Debug("No pages need indexing")
		return
	}

	s.logger.Info("Indexing pages",
		zap.Int("page_count", len(pages)),
	)

	successCount := 0
	failCount := 0

	for _, page := range pages {
		if err := s.indexPage(ctx, page); err != nil {
			s.logger.Error("Failed to index page",
				zap.Int64("page_id", page.ID),
				zap.String("page_title", page.Title),
				zap.Error(err),
			)
			failCount++
		} else {
			successCount++
		}
	}

	s.logger.Info("Indexing completed",
		zap.Int("success", successCount),
		zap.Int("failed", failCount),
	)
}

// indexPage indexes a single wiki page
func (s *Server) indexPage(ctx context.Context, page *ent.WikiPage) error {
	// Get the latest snapshot for the page
	snapshot, err := s.db.Client.PageVersion.Query().
		Where(pageversion.PageID(page.ID)).
		Order(ent.Desc(pageversion.FieldVersionNumber)).
		First(ctx)
	if err != nil {
		if ent.IsNotFound(err) {
			s.logger.Debug("No snapshot available for indexing",
				zap.Int64("page_id", page.ID),
			)
			return nil
		}
		return err
	}

	// Convert state to base64 for Yjs processor
	stateBase64 := base64.StdEncoding.EncodeToString(snapshot.YjsState)

	// Extract blocks from the snapshot
	blocks, err := s.yjsClient.ExtractBlocks(ctx, stateBase64)
	if err != nil {
		return err
	}

	// Delete existing blocks for this page
	_, err = s.db.Client.WikiBlock.Delete().
		Where(wikiblock.PageID(page.ID)).
		Exec(ctx)
	if err != nil {
		return err
	}

	// Insert new blocks
	if len(blocks) > 0 {
		bulk := make([]*ent.WikiBlockCreate, len(blocks))
		for i, block := range blocks {
			bulk[i] = s.db.Client.WikiBlock.Create().
				SetPageID(page.ID).
				SetBlockType(block.Type).
				SetHeadingsPath(block.HeadingsPath).
				SetPlainText(block.PlainText).
				SetPosition(block.Position)

			// Set optional level for headings
			if block.Level != nil {
				bulk[i].SetLevel(*block.Level)
			}

			// Store canonical JSON as string
			if block.CanonicalJSON != "" {
				bulk[i].SetCanonicalJSON(block.CanonicalJSON)
			}
		}

		_, err = s.db.Client.WikiBlock.CreateBulk(bulk...).Save(ctx)
		if err != nil {
			return err
		}
	}

	s.logger.Info("Indexed page",
		zap.Int64("page_id", page.ID),
		zap.String("page_title", page.Title),
		zap.Int("block_count", len(blocks)),
	)

	return nil
}

package api

import (
	"context"
	"sync"
	"time"

	"go.uber.org/zap"

	"taskai/internal/auth"
	"taskai/internal/collab"
	"taskai/internal/config"
	"taskai/internal/db"
	"taskai/internal/email"
	"taskai/internal/yjs"
)

// Server holds the application dependencies
type Server struct {
	db            *db.DB
	config        *config.Config
	logger        *zap.Logger
	emailService  *email.BrevoService
	emailMu       sync.RWMutex
	auth          *auth.Service
	collabManager *collab.Manager
	yjsClient     *yjs.Client
}

// NewServer creates a new API server
func NewServer(database *db.DB, cfg *config.Config, logger *zap.Logger) *Server {
	return &Server{
		db:     database,
		config: cfg,
		logger: logger,
	}
}

// SetAuthService sets the auth service
func (s *Server) SetAuthService(authService *auth.Service) {
	s.auth = authService
}

// SetCollabManager sets the collaboration manager
func (s *Server) SetCollabManager(manager *collab.Manager) {
	s.collabManager = manager
}

// SetYjsClient sets the Yjs processor client
func (s *Server) SetYjsClient(client *yjs.Client) {
	s.yjsClient = client
}

// getAppURL returns the application URL for use in email links
func (s *Server) getAppURL() string {
	if len(s.config.CORSAllowedOrigins) > 0 {
		return s.config.CORSAllowedOrigins[0]
	}
	return "http://localhost:5173"
}

// invalidateEmailService clears the cached email service so it's reloaded on next use
func (s *Server) invalidateEmailService() {
	s.emailMu.Lock()
	defer s.emailMu.Unlock()
	s.emailService = nil
}

// GetEmailService returns the email service, loading from DB if needed. Returns nil if not configured.
func (s *Server) GetEmailService() *email.BrevoService {
	s.emailMu.RLock()
	if s.emailService != nil {
		svc := s.emailService
		s.emailMu.RUnlock()
		return svc
	}
	s.emailMu.RUnlock()

	// Load from DB
	s.emailMu.Lock()
	defer s.emailMu.Unlock()

	// Double-check after acquiring write lock
	if s.emailService != nil {
		return s.emailService
	}

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	var apiKey, senderEmail, senderName, status string
	err := s.db.QueryRowContext(ctx,
		`SELECT api_key, sender_email, sender_name, status FROM email_provider WHERE id = 1`,
	).Scan(&apiKey, &senderEmail, &senderName, &status)
	if err != nil {
		return nil
	}

	if status == "suspended" {
		return nil
	}

	s.emailService = email.NewBrevoService(apiKey, senderEmail, senderName, s.logger)
	return s.emailService
}

package config

import (
	"os"
	"strconv"
	"strings"
	"time"
)

// Config holds application configuration
type Config struct {
	// Server
	Port string
	Env  string

	// Database
	DBDriver       string // "sqlite" or "postgres"
	DBPath         string // For SQLite
	DBDSN          string // For Postgres
	MigrationsPath string

	// JWT
	JWTSecret      string
	JWTExpiryHours int

	// CORS
	CORSAllowedOrigins []string

	// Rate Limiting
	RateLimitRequests       int
	RateLimitWindowMinutes  int

	// Logging
	LogLevel       string
	EnableSQLLog   bool

	// Profiling
	EnablePprof    bool

	// Database
	DBQueryTimeout time.Duration

	// Yjs Processor
	YJSProcessorURL string

	// GitHub OAuth (repo integration)
	GitHubClientID     string
	GitHubClientSecret string
	AppURL             string

	// OAuth Login (Google + GitHub login, separate from repo integration)
	GoogleClientID          string
	GoogleClientSecret      string
	LoginGitHubClientID     string
	LoginGitHubClientSecret string
	OAuthStateSecret        string
	OAuthSuccessURL         string
	OAuthErrorURL           string

	// Backup (Google Drive) — reuses GOOGLE_CLIENT_ID/SECRET from OAuth login
	BackupEncryptionKey string // 64-char hex-encoded 32-byte AES key
}

// Load reads configuration from environment variables
func Load() *Config {
	dbDriver := getEnv("DB_DRIVER", "postgres")

	cfg := &Config{
		Port:                    getEnv("PORT", "8080"),
		Env:                     getEnv("ENV", "development"),
		DBDriver:                dbDriver,
		DBPath:                  getEnv("DB_PATH", "./data/taskai.db"),
		DBDSN:                   getEnv("DB_DSN", ""),
		MigrationsPath:          getEnv("MIGRATIONS_PATH", "./internal/db/migrations"),
		JWTSecret:               getEnv("JWT_SECRET", "change-this-to-a-secure-random-string-in-production"),
		JWTExpiryHours:          getEnvAsInt("JWT_EXPIRY_HOURS", 24),
		CORSAllowedOrigins:      getEnvAsSlice("CORS_ALLOWED_ORIGINS", []string{"http://localhost:5173", "http://localhost:3000"}),
		RateLimitRequests:       getEnvAsInt("RATE_LIMIT_REQUESTS", 100),
		RateLimitWindowMinutes:  getEnvAsInt("RATE_LIMIT_WINDOW_MINUTES", 15),
		LogLevel:                getEnv("LOG_LEVEL", "info"),
		EnableSQLLog:            getEnv("ENV", "development") == "development" || getEnv("ENABLE_SQL_LOG", "false") == "true",
		EnablePprof:             getEnv("ENABLE_PPROF", "false") == "true",
		DBQueryTimeout:          time.Duration(getEnvAsInt("DB_QUERY_TIMEOUT_SECONDS", 5)) * time.Second,
		YJSProcessorURL:         getEnv("YJS_PROCESSOR_URL", "http://localhost:3001"),
		GitHubClientID:          getEnv("GITHUB_CLIENT_ID", ""),
		GitHubClientSecret:      getEnv("GITHUB_CLIENT_SECRET", ""),
		AppURL:                  getEnv("APP_URL", "http://localhost:5173"),
		GoogleClientID:          getEnv("GOOGLE_CLIENT_ID", ""),
		GoogleClientSecret:      getEnv("GOOGLE_CLIENT_SECRET", ""),
		LoginGitHubClientID:     getEnv("LOGIN_GITHUB_CLIENT_ID", ""),
		LoginGitHubClientSecret: getEnv("LOGIN_GITHUB_CLIENT_SECRET", ""),
		OAuthStateSecret:        getEnv("OAUTH_STATE_SECRET", ""),
		OAuthSuccessURL:         getEnv("OAUTH_SUCCESS_URL", "http://localhost:5173/oauth/callback"),
		OAuthErrorURL:           getEnv("OAUTH_ERROR_URL", "http://localhost:5173/login"),

		BackupEncryptionKey: getEnv("BACKUP_ENCRYPTION_KEY", ""),
	}

	// Validate critical configuration
	if cfg.Env == "production" && cfg.JWTSecret == "change-this-to-a-secure-random-string-in-production" {
		logger := MustInitLogger(cfg.Env, cfg.LogLevel)
		logger.Fatal("JWT_SECRET must be set in production environment")
	}

	return cfg
}

// JWTExpiry returns the JWT expiry duration
func (c *Config) JWTExpiry() time.Duration {
	return time.Duration(c.JWTExpiryHours) * time.Hour
}

// getEnv reads an environment variable or returns a default value
func getEnv(key, defaultValue string) string {
	if value := os.Getenv(key); value != "" {
		return value
	}
	return defaultValue
}

// getEnvAsInt reads an environment variable as int or returns a default value
func getEnvAsInt(key string, defaultValue int) int {
	valueStr := os.Getenv(key)
	if valueStr == "" {
		return defaultValue
	}
	value, err := strconv.Atoi(valueStr)
	if err != nil {
		// Silently use default - logger not available yet during config load
		return defaultValue
	}
	return value
}

// getEnvAsSlice reads an environment variable as comma-separated values
func getEnvAsSlice(key string, defaultValue []string) []string {
	valueStr := os.Getenv(key)
	if valueStr == "" {
		return defaultValue
	}

	var result []string
	for _, v := range strings.Split(valueStr, ",") {
		if trimmed := strings.TrimSpace(v); trimmed != "" {
			result = append(result, trimmed)
		}
	}

	if len(result) == 0 {
		return defaultValue
	}
	return result
}

package api

import (
	"context"
	"encoding/json"
	"net/http"
	"strconv"
	"time"

	"go.uber.org/zap"

	"taskai/ent"
	"taskai/ent/projectmember"
	"taskai/ent/wikiblock"
	"taskai/ent/wikipage"
)

// SearchWikiRequest represents a wiki search request
type SearchWikiRequest struct {
	Query       string `json:"query"`
	ProjectID   *int64 `json:"project_id,omitempty"`
	Limit       int    `json:"limit,omitempty"`
	RecencyDays *int   `json:"recency_days,omitempty"`
}

// SearchResultBlock represents a search result block
type SearchResultBlock struct {
	PageID       int64   `json:"page_id"`
	PageTitle    string  `json:"page_title"`
	PageSlug     string  `json:"page_slug"`
	BlockID      int64   `json:"block_id"`
	BlockType    string  `json:"block_type"`
	HeadingsPath string  `json:"headings_path,omitempty"`
	Snippet      string  `json:"snippet"`
	Rank         float64 `json:"rank,omitempty"`
}

// SearchWikiResponse represents a wiki search response
type SearchWikiResponse struct {
	Results []SearchResultBlock `json:"results"`
	Total   int                 `json:"total"`
}

// HandleSearchWiki performs full-text search across wiki content
func (s *Server) HandleSearchWiki(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 10*time.Second)
	defer cancel()

	userID, ok := ctx.Value(UserIDKey).(int64)
	if !ok {
		respondError(w, http.StatusUnauthorized, "unauthorized", "unauthorized")
		return
	}

	var req SearchWikiRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		respondError(w, http.StatusBadRequest, "invalid request body", "invalid_request")
		return
	}

	if req.Query == "" {
		respondError(w, http.StatusBadRequest, "query parameter is required", "invalid_request")
		return
	}

	// Set defaults
	if req.Limit == 0 {
		req.Limit = 20
	}
	if req.Limit > 100 {
		req.Limit = 100
	}

	s.logger.Debug("Wiki search request",
		zap.String("query", req.Query),
		zap.Int64("user_id", userID),
	)

	// Build query based on database driver
	results, err := s.searchWikiBlocks(ctx, userID, req)
	if err != nil {
		s.logger.Error("Failed to search wiki",
			zap.Error(err),
			zap.String("query", req.Query),
		)
		respondError(w, http.StatusInternalServerError, "failed to search wiki", "internal_error")
		return
	}

	response := SearchWikiResponse{
		Results: results,
		Total:   len(results),
	}

	respondJSON(w, http.StatusOK, response)
}

// searchWikiBlocks performs the actual search query
func (s *Server) searchWikiBlocks(ctx context.Context, userID int64, req SearchWikiRequest) ([]SearchResultBlock, error) {
	// Get user's accessible project IDs
	accessibleProjects, err := s.getUserAccessibleProjects(ctx, userID)
	if err != nil {
		return nil, err
	}

	if len(accessibleProjects) == 0 {
		return []SearchResultBlock{}, nil
	}

	// Build base query — select only columns that exist in both SQLite and Postgres
	query := s.db.Client.WikiBlock.Query().
		Select(
			wikiblock.FieldID,
			wikiblock.FieldPageID,
			wikiblock.FieldBlockType,
			wikiblock.FieldLevel,
			wikiblock.FieldHeadingsPath,
			wikiblock.FieldPlainText,
			wikiblock.FieldPosition,
		).
		WithPage(func(q *ent.WikiPageQuery) {
			q.Select(wikipage.FieldID, wikipage.FieldTitle, wikipage.FieldSlug, wikipage.FieldProjectID)
		})

	// Filter by project if specified
	if req.ProjectID != nil {
		query = query.Where(wikiblock.HasPageWith(wikipage.ProjectID(*req.ProjectID)))
	} else {
		// Filter by accessible projects
		query = query.Where(wikiblock.HasPageWith(wikipage.ProjectIDIn(accessibleProjects...)))
	}

	// Use ContainsFold for case-insensitive search (generates ILIKE on Postgres)
	query = query.Where(wikiblock.Or(
		wikiblock.PlainTextContainsFold(req.Query),
		wikiblock.HeadingsPathContainsFold(req.Query),
	))

	// Apply recency filter if specified
	if req.RecencyDays != nil && *req.RecencyDays > 0 {
		cutoff := time.Now().AddDate(0, 0, -*req.RecencyDays)
		query = query.Where(wikiblock.HasPageWith(wikipage.UpdatedAtGTE(cutoff)))
	}

	// Execute query with limit
	blocks, err := query.
		Limit(req.Limit).
		All(ctx)
	if err != nil {
		return nil, err
	}

	// Convert to response format
	results := make([]SearchResultBlock, 0, len(blocks))
	for _, block := range blocks {
		page := block.Edges.Page
		if page == nil {
			continue
		}

		snippet := ""
		if block.PlainText != nil {
			snippet = *block.PlainText
			if len(snippet) > 200 {
				snippet = snippet[:200] + "..."
			}
		}

		headingsPath := ""
		if block.HeadingsPath != nil {
			headingsPath = *block.HeadingsPath
		}

		results = append(results, SearchResultBlock{
			PageID:       page.ID,
			PageTitle:    page.Title,
			PageSlug:     page.Slug,
			BlockID:      block.ID,
			BlockType:    block.BlockType,
			HeadingsPath: headingsPath,
			Snippet:      snippet,
		})
	}

	return results, nil
}

// AutocompletePageRequest represents a page autocomplete request
type AutocompletePageRequest struct {
	Query     string `json:"query"`
	ProjectID *int64 `json:"project_id,omitempty"`
	Limit     int    `json:"limit,omitempty"`
}

// AutocompletePageResult represents an autocomplete result
type AutocompletePageResult struct {
	ID    int64  `json:"id"`
	Title string `json:"title"`
	Slug  string `json:"slug"`
}

// HandleAutocompletePages provides fuzzy page title autocomplete
func (s *Server) HandleAutocompletePages(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 5*time.Second)
	defer cancel()

	userID, ok := ctx.Value(UserIDKey).(int64)
	if !ok {
		respondError(w, http.StatusUnauthorized, "unauthorized", "unauthorized")
		return
	}

	// Parse query parameters
	query := r.URL.Query().Get("query")
	if query == "" {
		respondJSON(w, http.StatusOK, []AutocompletePageResult{})
		return
	}

	limit := 10
	if limitStr := r.URL.Query().Get("limit"); limitStr != "" {
		if parsedLimit, err := strconv.Atoi(limitStr); err == nil && parsedLimit > 0 {
			limit = parsedLimit
			if limit > 50 {
				limit = 50
			}
		}
	}

	var projectID *int64
	if projectIDStr := r.URL.Query().Get("project_id"); projectIDStr != "" {
		if parsedID, err := strconv.ParseInt(projectIDStr, 10, 64); err == nil {
			projectID = &parsedID
		}
	}

	// Get user's accessible projects
	accessibleProjects, err := s.getUserAccessibleProjects(ctx, userID)
	if err != nil {
		s.logger.Error("Failed to get accessible projects",
			zap.Error(err),
		)
		respondError(w, http.StatusInternalServerError, "failed to get accessible projects", "internal_error")
		return
	}

	if len(accessibleProjects) == 0 {
		respondJSON(w, http.StatusOK, []AutocompletePageResult{})
		return
	}

	// Build query
	pageQuery := s.db.Client.WikiPage.Query()

	// Filter by project if specified
	if projectID != nil {
		pageQuery = pageQuery.Where(wikipage.ProjectID(*projectID))
	} else {
		pageQuery = pageQuery.Where(wikipage.ProjectIDIn(accessibleProjects...))
	}

	// Simple title contains search (can be enhanced with trigram similarity for Postgres)
	pageQuery = pageQuery.Where(wikipage.TitleContains(query))

	// Execute query
	pages, err := pageQuery.
		Limit(limit).
		Order(ent.Asc(wikipage.FieldTitle)).
		All(ctx)
	if err != nil {
		s.logger.Error("Failed to autocomplete pages",
			zap.Error(err),
		)
		respondError(w, http.StatusInternalServerError, "failed to autocomplete pages", "internal_error")
		return
	}

	// Convert to response format
	results := make([]AutocompletePageResult, len(pages))
	for i, page := range pages {
		results[i] = AutocompletePageResult{
			ID:    page.ID,
			Title: page.Title,
			Slug:  page.Slug,
		}
	}

	respondJSON(w, http.StatusOK, results)
}

// getUserAccessibleProjects returns the list of project IDs the user has access to
// via a single query on the project_members table (avoids N+1 queries).
func (s *Server) getUserAccessibleProjects(ctx context.Context, userID int64) ([]int64, error) {
	members, err := s.db.Client.ProjectMember.Query().
		Where(projectmember.UserID(userID)).
		Select(projectmember.FieldProjectID).
		All(ctx)
	if err != nil {
		return nil, err
	}

	projectIDs := make([]int64, 0, len(members))
	for _, m := range members {
		projectIDs = append(projectIDs, m.ProjectID)
	}

	return projectIDs, nil
}

package main

import (
	"context"
	"encoding/hex"
	"fmt"
	"net/http"
	"net/http/pprof"
	"os"
	"strings"
	"os/signal"
	"syscall"
	"time"

	godraw "github.com/anchoo2kewl/go-draw"
	godrawstore "github.com/anchoo2kewl/go-draw/store"
	backup "github.com/anchoo2kewl/go-backup"
	backupgdrive "github.com/anchoo2kewl/go-backup/gdrive"
	backuppgstore "github.com/anchoo2kewl/go-backup/pgstore"
	gologin "github.com/anchoo2kewl/go-login"
	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
	"github.com/go-chi/cors"
	"github.com/golang-jwt/jwt/v5"
	"go.opentelemetry.io/contrib/instrumentation/net/http/otelhttp"
	"go.uber.org/zap"

	"taskai/apm"
	"taskai/internal/api"
	"taskai/internal/auth"
	"taskai/internal/collab"
	"taskai/internal/config"
	"taskai/internal/db"
	"taskai/internal/version"
	"taskai/internal/yjs"
)

func getEnv(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

// isLoginOAuthState returns true if tokenStr is a valid login OAuth state JWT
// signed with stateSecret (contains a "provider" claim).
// Used to distinguish login callbacks from repo-sync callbacks at /api/auth/github/callback.
func isLoginOAuthState(tokenStr, stateSecret string) bool {
	if stateSecret == "" || tokenStr == "" {
		return false
	}
	token, err := jwt.Parse(tokenStr, func(t *jwt.Token) (interface{}, error) {
		if _, ok := t.Method.(*jwt.SigningMethodHMAC); !ok {
			return nil, fmt.Errorf("unexpected signing method")
		}
		return []byte(stateSecret), nil
	})
	if err != nil || !token.Valid {
		return false
	}
	claims, ok := token.Claims.(jwt.MapClaims)
	if !ok {
		return false
	}
	_, hasProvider := claims["provider"]
	return hasProvider
}

func main() {
	// Load configuration
	cfg := config.Load()

	// Initialize logger
	logger := config.MustInitLogger(cfg.Env, cfg.LogLevel)
	defer logger.Sync() // Flush any buffered log entries

	logger.Info("Starting TaskAI API",
		zap.String("env", cfg.Env),
		zap.String("port", cfg.Port),
	)

	// Initialize APM (OpenTelemetry → Datadog via otel-collector).
	// When APM_ENABLED != "true" this is a zero-cost noop.
	apmCfg := apm.ConfigFromEnv(version.Version)
	apmShutdown, err := apm.Init(context.Background(), apmCfg)
	if err != nil {
		logger.Fatal("failed to init APM tracer", zap.Error(err))
	}
	defer func() {
		if err := apmShutdown(context.Background()); err != nil {
			logger.Warn("APM shutdown error", zap.Error(err))
		}
	}()
	if apmCfg.Enabled {
